# Tiny ontology with subclass reasoning
subclass = {"Dog": "Mammal", "Mammal": "Animal", "Animal": "Organism"}
individuals = {"fido": "Dog", "whiskers": "Cat"}
subclass["Cat"] = "Mammal"
def ancestors(cls):
    out = []
    while cls in subclass:
        cls = subclass[cls]; out.append(cls)
    return out
for name, cls in individuals.items():
    print(f"{name} is a {cls}; ancestors: {ancestors(cls)}")
